import subprocess, os, json

def get_map(css, minify=False):
    for f in ["/tmp/out.css","/tmp/out.css.map"]:
        try: os.remove(f)
        except: pass
    args = ['-o', '/tmp/out.css', '--sourcemap'] + (["--minify"] if minify else [])
    p = subprocess.run(['/workspace/executable']+args, input=css.encode(), capture_output=True)
    if p.returncode!=0:
        return f"ERR {p.stderr.decode()[:200]}"
    m = json.loads(open("/tmp/out.css.map").read())
    css_out = open("/tmp/out.css","rb").read()
    for f in ["/tmp/out.css","/tmp/out.css.map"]:
        try: os.remove(f)
        except: pass
    return m["mappings"], css_out[:500]

tests = [
    ".foo{color:red}",
    ".foo{color:red}.bar{color:blue}",
    ".foo{color:red}\n.bar{color:blue}",
    "@media (min-width:100px){.foo{color:red}}",
    "@keyframes foo{from{color:red}to{color:blue}}",
    ".foo{color:red}/* comment */.bar{color:blue}",
    "/*! a */.foo{color:red}/*! b */.bar{color:blue}",
    ".foo{color:red}.foo{color:blue}",  # merged?
]

for css in tests:
    for minify in [False, True]:
        mappings, out = get_map(css, minify)
        print(f"css={repr(css)[:60]} minify={minify} mappings={repr(mappings)} out={repr(out[:200])}")
PY
"}

