VERSION_TEXT = b'lightningcss 1.0.0-alpha.70\n'

def eprint_bytes(b):
    sys.stderr.buffer.write(b)

def print_help():
    sys.stdout.buffer.write(HELP_TEXT)

def print_version():
    sys.stdout.buffer.write(VERSION_TEXT)

def errno_to_kind(code):
    if code == 2:
        return "NotFound"
    elif code == 20:
        return "NotADirectory"
    elif code == 21:
        return "IsADirectory"
    elif code == 17:
        return "AlreadyExists"
    elif code == 13 or code == 1:
        return "PermissionDenied"
    elif code == 22:
        return "InvalidInput"
    else:
        return "Uncategorized"

def os_error_exit(e):
    code = e.errno if e.errno is not None else 1
    kind = errno_to_kind(code)
    msg = e.strerror if e.strerror else "Unknown error"
    eprint_bytes(f'Error: Os {{ code: {code}, kind: {kind}, message: "{msg}" }}\n'.encode())
    sys.exit(1)

def panic_exit(msg, loc_line=187, loc_col=45, filename="src/main.rs"):
    pid = os.getpid()
    text = f"\nthread 'main' ({pid}) panicked at {filename}:{loc_line}:{loc_col}:\n{msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    eprint_bytes(text.encode())
    try:
        sys.stderr.flush()
    except:
        pass
    os.abort()

PYEOF
